RETRYABLE = {429, 500, 502, 503, 504}

for status in [200, 400, 401, 404, 429, 500, 503]:
    if status < 400:
        verdict = "success"
    elif status in RETRYABLE:
        verdict = "retry with backoff"
    else:
        verdict = "do not retry - fix the request"
    print(f"{status}: {verdict}")
